mapper.select:
SELECT application_user_id AS user_id , user_name AS employee_no , english_full_name AS employee_name , full_name_local AS local_employee_name , organization_name_eng AS department_name , system_code AS default_system_code , mail_addr , susp_resignation_name , language_code , TO_CHAR(apply_start_date,'YYYY-MM-DD') AS apply_start_date , TO_CHAR(apply_end_date,'YYYY-MM-DD') AS apply_end_date , request_region_code , request_region_name , CASE WHEN server_time_difference_seqs > 0 THEN 'GMT + ' || ABS(server_time_difference_seqs) WHEN server_time_difference_seqs < 0 THEN 'GMT - ' || ABS(server_time_difference_seqs) END AS time_zone_name , NVL(request_region_code_use_flag,'N') AS region_use_flag , NVL(request_region_code_use_flag,'N') AS orgin_region_use_flag , DECODE(ou_use_flag,'Y',default_org_id) AS default_org_id , DECODE(ou_use_flag,'Y',default_org_name) AS default_org_name , NVL(default_org_id_use_flag,'N') AS org_use_flag , screen_design_theme_id , NVL(menu_use_flag,'N') AS menu_use_flag , ou_use_flag FROM LGCOM_USER_M_V umv WHERE 1 = 1
AND organization_name_eng LIKE #{deptName} || '%'
AND application_user_id = #{userId}
AND user_name = #{employeeNo}
AND (UPPER(english_full_name) LIKE UPPER(#{employeeName}) || '%' OR UPPER(full_name_local) LIKE UPPER(#{employeeName}) || '%')
AND mail_addr LIKE #{mailAddr} || '%'
AND susp_resignation_flag = #{suspResignationFlag}
ORDER BY application_user_id

mapper.update:
UPDATE LGCOM_USER_M
   SET language_code                = #{languageCode}
     , system_code                  = #{defaultSystemCode}
     , default_org_id_use_flag      = #{orgUseFlag}
     , screen_design_theme_id       = #{screenDesignThemeId}
     , menu_use_flag                = #{menuUseFlag}
     , last_updated_by              = #{sessionUserId}
     , last_update_date             = SYSDATE
 WHERE application_user_id          = #{userId}

UPDATE LGCOM_USER_M
   SET request_region_code_use_flag = #{regionUseFlag}
     , last_updated_by              = #{sessionUserId}
     , last_update_date             = SYSDATE
 WHERE mail_addr = #{mailAddr}
